using DangPhatFlex.Web.Models;
using DangPhatFlex.Web.Services;

namespace DangPhatFlex.Web.Data;

// One-off backlog of 24 SEO articles (2/day, 8:00 & 17:00, 20/07-31/07/2026) targeting the
// 3 committed keyword phrases. Kept separate from DbSeeder.BuildNewsArticles (the original 3
// launch articles) to avoid bloating that file further. Idempotent: checks for the first
// backlog article's slug before inserting, so re-running on an already-seeded database is a no-op.
public static class NewsBacklogSeeder
{
    public static void Seed(AppDbContext context, ISlugService slugService)
    {
        var markerSlug = slugService.GenerateSlug("5 sai lầm thường gặp khi thi công ống mềm nối đầu phun sprinkler");
        if (context.NewsArticles.Any(a => a.Slug == markerSlug))
            return;

        var articles = BuildArticles();

        foreach (var article in articles)
            article.Slug = slugService.GenerateSlug(article.Title);

        context.NewsArticles.AddRange(articles);
        context.SaveChanges();
    }

